52									Pair<String, Integer> activeKeeperMaster,
53									RouteMeta routeForActiveKeeper,
54									SimpleKeyedObjectPool<Endpoint, NettyClient> clientPool
55				, int delayBaseMilli, int retryTimes, ScheduledExecutorService scheduled, Executor executors){
56			this.keepers = new LinkedList<>(keepers);
57			this.activeKeeperMaster = activeKeeperMaster;
58			this.routeForActiveKeeper = routeForActiveKeeper;
59			this.clientPool = clientPool;
60			this.delayBaseMilli = delayBaseMilli;
