71		@Override
72		protected void doExecute() throws CommandExecutionException {
73	
74			KeeperMeta activeKeeper = null;
75			for(KeeperMeta keeperMeta : keepers){
76				if(keeperMeta.isActive()){
77					activeKeeper = keeperMeta;
78					break;
79				}
80			}
81	
82			if(activeKeeper == null){
83				future().setFailure(new Exception("can not find active keeper:" + keepers));
84				return;
85			}
86			SequenceCommandChain chain = new SequenceCommandChain(false);
87	
88			if(activeKeeperMaster != null){
89				Command<?> setActiveCommand = createKeeperSetStateCommand(activeKeeper, activeKeeperMaster);
90				addActiveCommandHook(setActiveCommand);
91				chain.add(setActiveCommand);
92			}
93	
94			ParallelCommandChain backupChain = new ParallelCommandChain(executors);
95			
96			for(KeeperMeta keeperMeta : keepers){
97				if(!keeperMeta.isActive()){
98					Command<?> backupCommand = createKeeperSetStateCommand(keeperMeta, new Pair<String, Integer>(activeKeeper.getIp(), activeKeeper.getPort()));
99					backupChain.add(backupCommand);
100				}
101			}
102	
103			chain.add(backupChain);
104			
105			chain.execute().addListener(new CommandFutureListener<Object>() {
106				
107				@Override
108				public void operationComplete(CommandFuture<Object> commandFuture) throws Exception {
109					
110					if(commandFuture.isSuccess()){
111						future().setSuccess(null);
112					}else{
113						future().setFailure(commandFuture.cause());
114					}
115				}
116			});
117		}
