122	
123			KeeperSetStateCommand command =  new KeeperSetStateCommand(pool,
124					keeper.isActive() ? KeeperState.ACTIVE : KeeperState.BACKUP,
125					masterAddress,
126					keeper.isActive() ? routeForActiveKeeper : null,
127					scheduled);
128			return CommandRetryWrapper.buildCountRetry(retryTimes, new RetryDelay(delayBaseMilli), command, scheduled);
129		}
