	/**
	 * Detects whether the given cluster-shard is undergoing a datacenter migration.
	 *
	 * <p>During normal operation the keeper master of a shard whose primary datacenter is the current
	 * datacenter should point to one of the shard's known redis instances. When a migration is in
	 * progress (either a primary-dc migration or an other-dc migration) the current datacenter is still
	 * reported as primary while the keeper master no longer matches any of the shard's redises. In that
	 * case keeper state must not be corrected to avoid disrupting the migration.</p>
	 */
	protected boolean isClusterShardMigrating(String clusterId, String shardId) {
		if (metaCache == null || !metaCache.isCurrentDcPrimary(clusterId)) {
			return false;
		}
		Pair<String, Integer> keeperMaster = currentMetaManager.getKeeperMaster(clusterId, shardId);
		if (keeperMaster == null) {
			return false;
		}
		List<RedisMeta> shardRedises = metaCache.getShardRedises(clusterId, shardId);
		if (shardRedises != null) {
			for (RedisMeta redisMeta : shardRedises) {
				if (ObjectUtils.equals(redisMeta.getIp(), keeperMaster.getKey())
						&& ObjectUtils.equals(redisMeta.getPort(), keeperMaster.getValue())) {
					return false;
				}
			}
