347		/**
348		 * Detects whether the given cluster-shard is undergoing a datacenter migration.
349		 *
350		 * <p>During normal operation the keeper master of a shard whose primary datacenter is the current
351		 * datacenter should point to one of the shard's known redis instances. When a migration is in
352		 * progress (either a primary-dc migration or an other-dc migration) the current datacenter is still
353		 * reported as primary while the keeper master no longer matches any of the shard's redises. In that
354		 * case keeper state must not be corrected to avoid disrupting the migration.</p>
355		 */
356		protected boolean isClusterShardMigrating(String clusterId, String shardId) {
357			if (metaCache == null || !metaCache.isCurrentDcPrimary(clusterId)) {
358				return false;
359			}
360			Pair<String, Integer> keeperMaster = currentMetaManager.getKeeperMaster(clusterId, shardId);
361			if (keeperMaster == null) {
362				return false;
363			}
364			List<RedisMeta> shardRedises = metaCache.getShardRedises(clusterId, shardId);
365			if (shardRedises != null) {
366				for (RedisMeta redisMeta : shardRedises) {
367					if (ObjectUtils.equals(redisMeta.getIp(), keeperMaster.getKey())
368							&& ObjectUtils.equals(redisMeta.getPort(), keeperMaster.getValue())) {
369						return false;
370					}
371				}
372			}
373			return true;
374		}
